        function createParticles() {
            const container = document.getElementById('particles');
            const particleCount = window.innerWidth > 768 ? 30 : 15;

            for (let i = 0; i < particleCount; i++) {
                const particle = document.createElement('div');
                particle.className = 'particle';
                particle.style.left = Math.random() * 100 + '%';
                particle.style.animationDelay = Math.random() * 8 + 's';
                particle.style.animationDuration = (Math.random() * 4 + 6) + 's';
                container.appendChild(particle);
            }
        }

        function loadSettings() {
            const savedTheme = localStorage.getItem('notionTheme') || 'dark';
            const savedFontSize = localStorage.getItem('notionFontSize') || 'medium';

            setTheme(savedTheme, false);
            setFontSize(savedFontSize, false);
        }

        function toggleSettings() {
            const options = document.getElementById('settingsOptions');
            options.classList.toggle('show');
        }

        function setFontSize(size, save = true) {
            const contentText = document.getElementById('contentText');
            const buttons = document.querySelectorAll('.settings-section:first-child .settings-btn');

            buttons.forEach(btn => btn.classList.remove('active'));
            document.querySelector(`[data-size="${size}"]`).classList.add('active');

            contentText.className = 'content-text font-' + size;

            if (save) {
                localStorage.setItem('notionFontSize', size);
