            const body = document.body;
            const buttons = document.querySelectorAll('.settings-section:last-child .settings-btn');

            buttons.forEach(btn => btn.classList.remove('active'));
            document.querySelector(`[data-theme="${theme}"]`).classList.add('active');

            body.className = theme === 'dark' ? '' : 'theme-' + theme;

            const container = document.getElementById('particles');
            container.innerHTML = '';
            createParticles();

            if (save) {
                localStorage.setItem('notionTheme', theme);
            }
        }

        function timeClick(event) {
            event.stopPropagation();
            const element = event.currentTarget;
            element.style.transform = 'scale(0.95)';
            setTimeout(() => {
                element.style.transform = 'scale(1)';
            }, 150);
        }

        function locationClick(event) {
            event.stopPropagation();
            const element = event.currentTarget;
            element.style.transform = 'scale(0.95) rotate(5deg)';
            setTimeout(() => {
                element.style.transform = 'scale(1) rotate(0deg)';
            }, 150);
        }

        function toggleCopyright(event) {
            event.stopPropagation();
            const toggle = event.currentTarget;
            const content = document.getElementById('copyrightContent');

            toggle.classList.toggle('expanded');
            content.classList.toggle('show');
        }

        document.addEventListener('click', function(event) {
            const settingsPanel = document.querySelector('.settings-panel');
            const settingsOptions = document.getElementById('settingsOptions');

            if (!settingsPanel.contains(event.target) && settingsOptions.classList.contains('show')) {
                settingsOptions.classList.remove('show');
            }
        });

        window.addEventListener('load', () => {
            loadSettings();
            createParticles();
        });

        window.addEventListener('resize', () => {
            const container = document.getElementById('particles');
            container.innerHTML = '';
            createParticles();
        });
    </script>
</body>
</html>
