    <script>
        function updateProgressBar() {
            const winScroll = document.body.scrollTop || document.documentElement.scrollTop;
            const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            const scrolled = (winScroll / height) * 100;
            document.getElementById('progressBar').style.width = scrolled + '%';
        }

        window.addEventListener('scroll', updateProgressBar);

        function loadFontSize() {
            const savedFontSize = localStorage.getItem('notionFontSize') || 'medium';
            const contentText = document.getElementById('contentText');
            const buttons = document.querySelectorAll('.font-btn');

            buttons.forEach(btn => btn.classList.remove('active'));

            if (savedFontSize === 'small') {
                buttons[0].classList.add('active');
            } else if (savedFontSize === 'medium') {
                buttons[1].classList.add('active');
            } else if (savedFontSize === 'large') {
                buttons[2].classList.add('active');
            }

            contentText.className = 'content-text font-' + savedFontSize;
        }

        function toggleFontOptions() {
            const options = document.getElementById('fontOptions');
            options.classList.toggle('show');
        }

        function setFontSize(size) {
            const contentText = document.getElementById('contentText');
            const buttons = document.querySelectorAll('.font-btn');

            buttons.forEach(btn => btn.classList.remove('active'));
            event.target.classList.add('active');

            contentText.className = 'content-text font-' + size;

            localStorage.setItem('notionFontSize', size);
        }

        function toggleCopyright(event) {
            event.stopPropagation();
            const toggle = event.currentTarget;
            const content = document.getElementById('copyrightContent');

            toggle.classList.toggle('expanded');
            content.classList.toggle('show');
        }

        document.addEventListener('click', function(event) {
            const fontControls = document.querySelector('.font-controls');
            const fontOptions = document.getElementById('fontOptions');

            if (!fontControls.contains(event.target) && fontOptions.classList.contains('show')) {
                fontOptions.classList.remove('show');
            }
        });

        window.addEventListener('load', function() {
            loadFontSize();
            updateProgressBar();
        });
    </script>
